inline constexpr char kParticlesSort3DHlsl[] = R"hlsl(// Sorts a 3D particle system's slots by view depth, as Godot's particles sort buffer, a thread a
// slot of the system's amount rounded up to a power of two. Stage 0 makes each slot's key: its
// particle's depth along sort_direction as bits that order as the floats do, then its index, and
// keys after the last particle that sort last. The other stages are a bitonic sort's steps over
// the keys, comparing slots j apart in runs of k, so the keys end in the order the CPU twin's
// stable sort gives (particle_mesh_vertices_3d in src/particles3d.cpp): farthest first, ties by
// index. The steps are src/particle_layout_3d.cpp's bitonic_steps.

// What the 3D particle shaders share: the particle, as slash::render::Particle3D lays it out,
// particles.hlsl's flags and bindings, and the vector and transform helpers of
// src/particles3d.cpp.

// What particles_process.hlsl and particles_draw.hlsl share: the particle, as
// slash::render::Particle lays it out, and where SDL binds each kind of resource.

// One particle (96 bytes): basis is its x axis [x, y] then its y axis [z, w]; origin_velocity
// its origin [x, y] and velocity [z, w]; custom Godot's CUSTOM and userdata its USERDATA1.
struct Particle {
    float4 basis;
    float4 origin_velocity;
    float4 color;
    float4 custom;
    float4 userdata;
    uint4 flags; // .x; the rest is spare words
};

static const uint kParticleActive = 1u;
static const uint kParticleStarted = 2u;
static const uint kParticleTrailed = 4u;
static const uint kParticleCycleShift = 16u;

// SDL takes a compute shader's uniforms in space 2, what it reads in space 0 and writes in space
// 1. Metal has one list of buffers, uniforms first, so its SPIR-V is compiled with SLASH_MSL and
// the registers in that order.
#ifdef SLASH_MSL
#define UNIFORMS register(b0)
#define READ_ONLY register(t1)
#define READ_WRITE register(u2)
#else
#define UNIFORMS register(b0, space2)
#define READ_ONLY register(t0, space0)
#define READ_WRITE register(u0, space1)
#endif

// One particle (128 bytes): its transform's axes, each scaled, and its origin, their w 0; the
// velocity its forces built up and its flags; its color; Godot's CUSTOM (angle, age, frame,
// lifetime) and spare words.
struct Particle3D {
    float4 x;
    float4 y;
    float4 z;
    float4 origin;
    float3 velocity;
    uint flags;
    float4 color;
    float4 custom;
    float4 userdata;
};

// An affine transform: its axes and its origin.
struct Affine {
    float3 x;
    float3 y;
    float3 z;
    float3 origin;
};

float length_of(float3 v) {
    return sqrt(dot(v, v));
}

// v at length 1, or zero for zero, as the CPU twin's normalize.
float3 unit(float3 v) {
    float l = length_of(v);
    return l > 0.0 ? v / l : float3(0.0, 0.0, 0.0);
}

float3 basis(Affine a, float3 v) {
    return (a.x * v.x) + (a.y * v.y) + (a.z * v.z);
}

float3 apply(Affine a, float3 p) {
    return basis(a, p) + a.origin;
}

Affine inverse(Affine a) {
    float det = dot(a.x, cross(a.y, a.z));
    float inv = det != 0.0 ? 1.0 / det : 0.0;
    float3 r0 = cross(a.y, a.z) * inv;
    float3 r1 = cross(a.z, a.x) * inv;
    float3 r2 = cross(a.x, a.y) * inv;
    Affine out_;
    out_.x = float3(r0.x, r1.x, r2.x);
    out_.y = float3(r0.y, r1.y, r2.y);
    out_.z = float3(r0.z, r1.z, r2.z);
    out_.origin = basis(out_, a.origin) * -1.0;
    return out_;
}

cbuffer Params : UNIFORMS {
    uint amount;
    uint size;
    uint j;
    uint k;
    uint stage;
    uint pad0;
    uint pad1;
    uint pad2;
    float4 sort_direction;
};

StructuredBuffer<Particle3D> particles : READ_ONLY;
RWStructuredBuffer<uint2> keys : READ_WRITE;

// A float's bits, turned so that unsigned order is the floats' order; -0 sorts as 0.
uint order_bits(float value) {
    uint bits = value == 0.0 ? 0u : asuint(value);
    return (bits & 0x80000000u) != 0u ? ~bits : (bits | 0x80000000u);
}

bool after(uint2 a, uint2 b) {
    return a.x != b.x ? a.x > b.x : a.y > b.y;
}

[numthreads(64, 1, 1)]
void cs_main(uint3 id : SV_DispatchThreadID) {
    uint slot = id.x;
    if (slot >= size) {
        return;
    }
    if (stage == 0u) {
        if (slot < amount) {
            float depth = dot(sort_direction.xyz, particles[slot].origin.xyz);
            keys[slot] = uint2(order_bits(depth), slot);
        } else {
            keys[slot] = uint2(0xFFFFFFFFu, 0xFFFFFFFFu);
        }
        return;
    }
    uint other = slot ^ j;
    if (other <= slot) {
        return;
    }
    uint2 a = keys[slot];
    uint2 b = keys[other];
    bool ascending = (slot & k) == 0u;
    if (ascending ? after(a, b) : after(b, a)) {
        keys[slot] = b;
        keys[other] = a;
    }
}
)hlsl";

